import { getTelemetryMode } from '../config/telemetryPolicy';
import { PostHog } from 'posthog-node';
import { createLogger } from '../utils/logger';
import { getConfigManager } from './ConfigManager';
import { POSTHOG_PUBLIC_API_KEY } from '../config/posthog';
import { POSTHOG_HOST } from '../config/proxy';

const log = createLogger('FeatureFlagService');

const remoteFlagsDisabled = (): boolean => {
  const v = process.env.RIVET_DISABLE_REMOTE_FLAGS;
  return v !== undefined && v !== 'false' && v !== '0';
};

class FeatureFlagService {
  private posthog: PostHog | null = null;

  constructor() {
    if (remoteFlagsDisabled()) {
      log.info(
        'FeatureFlagService: remote flags disabled — using local defaults',
      );
      return;
    }
    try {
      this.posthog = new PostHog(POSTHOG_PUBLIC_API_KEY, {
        host: POSTHOG_HOST,
        flushAt: 1,
        flushInterval: 0,
        ...(getTelemetryMode() !== 'full'
          ? { personProfiles: 'never' as const, before_send: () => null }
          : {}),
      });
      log.info('FeatureFlagService initialized');
    } catch (error) {
      log.warn('Failed to initialize FeatureFlagService:', error);
    }
  }

  private get defaultUserKey(): string {
    return getConfigManager().getEmail() ?? getConfigManager().getAnonymousId();
  }

  private getUserKey(userKey: string | undefined): string {
    if (getTelemetryMode() !== 'full')
      return getConfigManager().getPluginTelemetryId();
    const trimmedUserKey = userKey?.trim();
    return trimmedUserKey && trimmedUserKey.length > 0
      ? trimmedUserKey
      : this.defaultUserKey;
  }

  async getAllFlags(
    userKey?: string,
  ): Promise<Record<string, boolean | string>> {
    if (!this.posthog) return {};

    try {
      return await this.posthog.getAllFlags(this.getUserKey(userKey), {
        disableGeoip: getTelemetryMode() !== 'full',
      });
    } catch (error) {
      log.warn('Failed to fetch feature flags:', error);
      return {};
    }
  }

  async isFeatureEnabled(
    key: string,
    userKey?: string,
  ): Promise<boolean | null> {
    if (!this.posthog) return null;

    try {
      const enabled = await this.posthog.isFeatureEnabled(
        key,
        this.getUserKey(userKey),
        {
          sendFeatureFlagEvents: getTelemetryMode() === 'full',
          disableGeoip: getTelemetryMode() !== 'full',
        },
      );
      return enabled ?? false;
    } catch (error) {
      log.warn(`Failed to evaluate feature flag "${key}":`, error);
      return null;
    }
  }

  async shutdown(): Promise<void> {
    if (this.posthog) {
      await this.posthog.shutdown();
      this.posthog = null;
    }
  }
}

let instance: FeatureFlagService | null = null;

export function getFeatureFlagService(): FeatureFlagService {
  if (!instance) {
    instance = new FeatureFlagService();
  }
  return instance;
}
